/**
 * Client-safe lookup. The slug list is generated by scripts/build-evergreen-prune.ts.
 * Importing this file does not read the filesystem.
 */
import slugs from "@/data/places/thin-zero-slugs.json";
import { searchPlaceHref } from "@/lib/prunedPlaces";

const THIN = new Set<string>(slugs as string[]);

export function isThinZeroSlug(code: string, slug: string): boolean {
  return THIN.has(`${code.toUpperCase()}/${slug}`);
}

/** Thin zero-impression place pages redirect to the state cities index. */
export function thinZeroRedirectTarget(pathname: string): string | null {
  const path = pathname.split("#")[0].split("?")[0].replace(/\/+$/, "");
  const city = path.match(/^\/cities\/([A-Za-z]{2})\/([^/]+)$/);
  if (!city || city[2] === "county") return null;
  const code = city[1].toUpperCase();
  if (!isThinZeroSlug(code, city[2])) return null;
  return `/cities/${code}/`;
}

/** ZIP and place-name search send thin zero-impression places to the state index. */
export function placeSearchHref(code: string, slug: string, fallbackPath: string): string {
  const pruned = searchPlaceHref(code, slug, fallbackPath);
  return thinZeroRedirectTarget(pruned) ?? thinZeroRedirectTarget(fallbackPath) ?? pruned;
}
